INSERT INTO approval_policies (id, key, name, description, mode, threshold, approvers_json, allow_self_approval, is_protected) VALUES ('policy:president-or-gs', 'president-or-gs', 'President or General Secretary', 'Either the President or the General Secretary approves.', 'ANY', NULL, '[{"type":"position","value":"president"},{"type":"position","value":"general-secretary"}]', 0, 0) ON CONFLICT(id) DO NOTHING;
INSERT INTO approval_policies (id, key, name, description, mode, threshold, approvers_json, allow_self_approval, is_protected) VALUES ('policy:president-and-gs', 'president-and-gs', 'President and General Secretary', 'Both the President and the General Secretary approve.', 'ALL', NULL, '[{"type":"position","value":"president"},{"type":"position","value":"general-secretary"}]', 0, 0) ON CONFLICT(id) DO NOTHING;
INSERT INTO approval_policies (id, key, name, description, mode, threshold, approvers_json, allow_self_approval, is_protected) VALUES ('policy:any-moderator', 'any-moderator', 'Any Moderator', 'One Moderator approves.', 'ANY', NULL, '[{"type":"role","value":"moderator"}]', 0, 0) ON CONFLICT(id) DO NOTHING;
INSERT INTO approval_policies (id, key, name, description, mode, threshold, approvers_json, allow_self_approval, is_protected) VALUES ('policy:two-moderators', 'two-moderators', 'Two Moderators', 'Two different Moderators approve (2 of 3).', 'THRESHOLD', 2, '[{"type":"role","value":"moderator"}]', 0, 0) ON CONFLICT(id) DO NOTHING;
INSERT INTO approval_policies (id, key, name, description, mode, threshold, approvers_json, allow_self_approval, is_protected) VALUES ('policy:leadership-any', 'leadership-any', 'Club leadership', 'The President, the General Secretary or a Moderator approves.', 'ANY', NULL, '[{"type":"position","value":"president"},{"type":"position","value":"general-secretary"},{"type":"role","value":"moderator"}]', 0, 0) ON CONFLICT(id) DO NOTHING;
INSERT INTO approval_policies (id, key, name, description, mode, threshold, approvers_json, allow_self_approval, is_protected) VALUES ('policy:governance-protected', 'governance-protected', 'Protected governance change', 'Changes to Moderator authority, protected rules and protected settings need approval from a second Moderator (the requester cannot approve their own change). With a single Moderator appointed, that Moderator acts alone and the change is audited.', 'THRESHOLD', 1, '[{"type":"role","value":"moderator"}]', 0, 1) ON CONFLICT(id) DO NOTHING;
